package main
import("strings";"strconv")
var _=strings.Compare
var _=strconv.Itoa
func solve(x map[string]any)any{s:=strings.ReplaceAll(x["text"].(string),"\r\n","\n");return strings.ReplaceAll(s,"\r","\n")}

